class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        # Sort tasks by their end times
        tasks.sort(key=lambda x: x[1])

        # Initialize a set to keep track of active tasks
        active_tasks = set()

        # Iterate through each task
        for start, end, duration in tasks:
            # Remove tasks that end before the current task starts
            active_tasks = {task for task in active_tasks if task <= start}

            # If there is no active task, turn on the computer
            if not active_tasks:
                active_tasks.add(end)
                duration -= 1

            # Add the remaining duration to the active tasks
            for i in range(start, min(end, start + duration)):
                active_tasks.add(i)

        # Return the total number of active tasks
        return len(active_tasks)

class Solution:
    def greatestLetter(self, s: str) -> str:
        seen_upper = set()
        seen_lower = set()
        for char in s:
            if char.isupper():
                seen_upper.add(char)
            elif char.islower():
                if char.upper() in seen_upper:
                    return char.upper()
                seen_lower.add(char)
        return ""

class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = collections.defaultdict(dict)

        # Build the graph
        for (numerator, denominator), value in zip(equations, values):
            graph[numerator][denominator] = value
            graph[denominator][numerator] = 1 / value

        def dfs(start, end, visited):
            if start not in graph or end not in graph:
                return -1.0
            if start == end:
                return 1.0

            visited.add(start)
            for neighbor, weight in graph[start].items():
                if neighbor not in visited:
                    result = dfs(neighbor, end, visited)
                    if result != -1.0:
                        return weight * result
            return -1.0

        results = []
        for query in queries:
            results.append(dfs(query[0], query[1], set()))

        return results

class Solution:
    def validPartition(self, nums: List[int]) -> bool:
        n = len(nums)
        dp = [False] * n

        # Base case: if there's only one element, it's always valid
        dp[0] = True

        # Iterate through the array
        for i in range(1, n):
            # Check if the current element is the same as the previous one
            if nums[i] == nums[i-1]:
                # If it's the first element, it's always valid
                if i == 1:
                    dp[i] = True
                else:
                    # If it's not the first element, check if the previous two elements form a valid partition
                    if dp[i-2] and nums[i] == nums[i-2]-1:
                        dp[i] = True

        # Return the result
        return dp[-1]

