from collections import defaultdict

class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        # Create a dictionary to store the last seen index of each number
        num_index_map = defaultdict(int)

        for i, num in enumerate(nums):
            # Check if there is a number in the dictionary whose absolute difference from the current number is less than or equal to valueDiff
            if i > indexDiff:
                del num_index_map[nums[i-indexDiff-1]]

            # If the number is already in the dictionary, check if the absolute difference between the current number and the stored number is less than or equal to valueDiff
            if num in num_index_map and abs(num - num_index_map[num]) <= valueDiff:
                return True

            # Update the last seen index of the current number
            num_index_map[num] = i

        return False

