class Solution:
    def squareFreeSubsets(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        primes = {2: 1, 3: 2, 5: 4, 6: 3, 7: 8, 10: 5, 11: 16, 13: 32, 14: 9, 15: 6, 17: 64, 19: 128, 21: 7, 22: 10, 23: 256, 26: 17, 29: 512, 30: 11}
        dp = [0] * 32
        dp[0] = 1

        for num in nums:
            mask = 0
            for p in primes:
                if num % (p * p) == 0:
                    mask |= primes[p]
                    break
            else:
                dp_new = dp[:]
                for i in range(32):
                    if i & mask == 0:
                        dp_new[i | mask] = (dp_new[i | mask] + dp[i]) % MOD
                dp = dp_new

        return (sum(dp) - 1) % MOD

