class Solution:
    def magnificentSets(self, n: int, edges: List[List[int]]) -> int:
        # Build the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Find all connected components
        visited = [False] * (n + 1)
        components = []

        def bfs(start):
            queue = deque([start])
            component = set()
            while queue:
                node = queue.popleft()
                if visited[node]:
                    continue
                visited[node] = True
                component.add(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
            return component

        for i in range(1, n + 1):
            if not visited[i]:
                components.append(bfs(i))

        # Function to calculate the maximum number of groups for a single component
        def max_groups_for_component(component):
            max_groups = 0
            for start in component:
                queue = deque([(start, 1)])
                visited = set([start])
                current_level = 0
                while queue:
                    level_size = len(queue)
                    for _ in range(level_size):
                        node, level = queue.popleft()
                        if level > current_level:
                            current_level = level
                        for neighbor in graph[node]:
                            if neighbor in component and neighbor not in visited:
                                if abs(level - (graph[neighbor][0] in visited)) != 1:
                                    return -1
                                visited.add(neighbor)
                                queue.append((neighbor, level + 1))
                max_groups = max(max_groups, current_level)
            return max_groups

        total_max_groups = 0
        for component in components:
            groups = max_groups_for_component(component)
            if groups == -1:
                return -1
            total_max_groups += groups

        return total_max_groups

class Solution:
    def minSwaps(self, s: str) -> int:
        # Count the number of '0's and '1's in the string
        zero_count = s.count('0')
        one_count = s.count('1')

        # If there's not enough '0's or '1's to swap, return -1
        if zero_count > one_count:
            return -1

        # Calculate the minimum number of swaps required
        # If there are an odd number of '1's, we need at least one more swap
        # If there are an even number of '1's, we need at most one less swap
        if one_count % 2 == 1:
            return one_count - 1
        else:
            return one_count // 2

class Solution:
    def longestUnivaluePath(self, root: Optional[TreeNode]) -> int:
        self.max_path = 0

        def dfs(node):
            if not node:
                return 0

            left_length = dfs(node.left)
            right_length = dfs(node.right)
            left_arrow = right_arrow = 0

            if node.left and node.left.val == node.val:
                left_arrow = left_length + 1
            if node.right and node.right.val == node.val:
                right_arrow = right_length + 1

            self.max_path = max(self.max_path, left_arrow + right_arrow)

            return max(left_arrow, right_arrow)

        dfs(root)
        return self.max_path

