class Solution:
    def wateringPlants(self, plants: List[int], capacity: int) -> int:
        i = 0
        ans = 0
        while i < len(plants):
            if capacity >= plants[i]:
                capacity -= plants[i]
                ans += 1
            else:
                ans += 2 * i + 1
                capacity = plants[i]
            i += 1
        return ans

