import heapq

class Solution:
    def allCellsDistOrder(self, rows: int, cols: int, rCenter: int, cCenter: int) -> List[List[int]]:
        heap = []
        for i in range(rows):
            for j in range(cols):
                dist = abs(i - rCenter) + abs(j - cCenter)
                heapq.heappush(heap, (dist, i, j))
        res = []
        while heap:
            _, i, j = heapq.heappop(heap)
            res.append([i, j])
        return res

class Solution:
    def minCost(self, nums: List[int], costs: List[int]) -> int:
        n = len(nums)
        dp = [float('inf')] * n
        dp[0] = 0

        for i in range(1, n):
            # For increasing sequence
            if nums[i] >= nums[i - 1]:
                dp[i] = min(dp[i], dp[i - 1] + costs[i])
            # For decreasing sequence
            else:
                for j in range(i):
                    if nums[i] <= nums[j]:
                        dp[i] = min(dp[i], dp[j] + costs[i])

        return dp[-1]

from functools import lru_cache

class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        MOD = 10**9 + 7

        @lru_cache(None)
        def dp(i, j):
            if i == len(grid) - 1 and j == len(grid[0]) - 1:
                return grid[i][j]

            res = float('-inf')
            for dx, dy in [(0, 1), (1, 0)]:
                nx, ny = i + dx, j + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                    res = max(res, dp(nx, ny))

            if res == float('-inf'):
                return -1

            return grid[i][j] * res % MOD

        return dp(0, 0)

class Solution:
    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        total_gas = sum(gas)
        total_cost = sum(cost)

        if total_gas < total_cost:
            return -1

        current_gas = 0
        start_index = 0

        for i in range(len(gas)):
            current_gas += gas[i] - cost[i]

            if current_gas < 0:
                start_index = i + 1
                current_gas = 0

        return start_index

