class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        # Check if there is only one node
        if len(leftChild) != len(rightChild):
            return False

        # Check if the root node has no left child
        if leftChild[0] == -1:
            return False

        # Check if the root node has no right child
        if rightChild[-1] == -1:
            return False

        # Recursively check the left and right subtrees
        return self.validateBinaryTreeNodes(n, leftChild[1:], rightChild[:-1])

