class Solution:
    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        if len(nums) < k:
            return False

        total_sum = sum(nums)
        if total_sum % k != 0:
            return False

        # Sort the array to make it easier to find subsets
        nums.sort()

        # Initialize the bitmask for each subset
        mask = 0
        for num in nums:
            if num > k:
                return False
            mask |= 1 << num

        # Try to partition the array into k subsets
        for i in range(1 << k):
            if self.can_partition_subarray(nums, i, mask):
                return True
        return False

    def can_partition_subarray(self, nums: List[int], index: int, mask: int) -> bool:
        if index == len(nums):
            return mask == 0

        # Skip duplicate elements
        if index > 0 and nums[index - 1] == nums[index]:
            return self.can_partition_subarray(nums, index + 1, mask)

        # Try including the current element
        if (mask & (1 << nums[index])) == 0:
            mask |= (1 << nums[index])
            if self.can_partition_subarray(nums, index + 1, mask):
                return True
            mask ^= (1 << nums[index])

        # Exclude the current element
        if (mask & (1 << nums[index])) == 0:
            mask ^= (1 << nums[index])
            if self.can_partition_subarray(nums, index + 1, mask):
                return True
            mask ^= (1 << nums[index])

        return False

