class Solution:
    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        total_tank, current_tank, starting_station = 0, 0, 0

        for i in range(len(gas)):
            total_tank += gas[i] - cost[i]
            current_tank += gas[i] - cost[i]

            if current_tank < 0:
                starting_station = i + 1
                current_tank = 0

        return starting_station if total_tank >= 0 else -1

class Solution:
    def findBall(self, grid: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        result = []

        for col in range(n):
            current_col = col
            for row in range(m):
                if grid[row][current_col] == 1:
                    # Check if the next cell is within bounds and not a V shape
                    if current_col + 1 < n and grid[row][current_col + 1] == 1:
                        current_col += 1
                    else:
                        break
                elif grid[row][current_col] == -1:
                    # Check if the previous cell is within bounds and not a V shape
                    if current_col - 1 >= 0 and grid[row][current_col - 1] == -1:
                        current_col -= 1
                    else:
                        break

            # If the ball fell out of the box, set the result to -1
            if current_col == col:
                result.append(-1)
            else:
                result.append(current_col)

        return result

class Solution:
    def nextGreaterElement(self, n: int) -> int:
        # Convert the number to a string to easily manipulate the digits
        str_n = str(n)

        # Iterate through the string from the end to the beginning
        for i in range(len(str_n) - 2, -1, -1):
            # Find the first digit that is smaller than the current digit
            for j in range(i + 1, len(str_n)):
                # If a smaller digit is found, swap them
                if str_n[i] < str_n[j]:
                    # Swap the digits
                    str_n[i], str_n[j] = str_n[j], str_n[i]
                    # Convert the string back to an integer
                    return int(''.join(str_n))

        # If no greater number exists, return -1
        return -1

