import heapq

class Solution:
    def minAbsDifference(self, nums: List[int], goal: int) -> int:
        n = len(nums)
        nums.sort()
        heap = []
        for num in nums:
            heapq.heappush(heap, num)

        res = float('inf')
        for i in range(n):
            left, right = 0, n-i-1
            while left <= right:
                mid = (left + right) // 2
                target = goal - nums[i]
                if mid == 0:
                    diff = abs(target - nums[mid])
                elif mid == n-i-1:
                    diff = abs(target - nums[n-i-1])
                else:
                    diff = abs(target - (nums[mid-1] + nums[mid+1]))

                if diff < res:
                    res = diff

                if target >= nums[mid]:
                    left = mid + 1
                else:
                    right = mid - 1

        return res

from collections import deque

class Solution:
    def slidingPuzzle(self, board: List[List[int]]) -> int:
        n = len(board)
        target = [[1, 2, 3], [4, 5, 0]]
        start_state = tuple([num for row in board for num in row])

        # BFS search
        queue = deque([(start_state, 0)])
        visited = set()

        while queue:
            current_state, moves = queue.popleft()

            if current_state == target:
                return moves

            for i in range(n):
                for j in range(n):
                    if current_state[i * n + j] == 0:
                        directions = [(i, j + 1), (i, j - 1), (i + 1, j), (i - 1, j)]

                        for dx, dy in directions:
                            if 0 <= dx < n and 0 <= dy < n:
                                new_state = list(current_state)
                                new_state[i * n + j], new_state[dx * n + dy] = new_state[dx * n + dy], new_state[i * n + j]

                                new_state_tuple = tuple(new_state)
                                if new_state_tuple not in visited:
                                    visited.add(new_state_tuple)
                                    queue.append((new_state_tuple, moves + 1))

        return -1

