class Solution:
    def minCost(self, costs: List[List[int]]) -> int:
        if not costs:
            return 0

        # Initialize the first row with the costs of painting the first house
        dp = [costs[0][0], costs[0][1], costs[0][2]]

        for i in range(1, len(costs)):
            # Calculate the minimum cost to paint the current house
            dp = [
                min(dp[(i-1)%3], dp[(i-2)%3]) + costs[i][0],
                min(dp[(i-1)%3], dp[(i-2)%3]) + costs[i][1],
                min(dp[(i-1)%3], dp[(i-2)%3]) + costs[i][2]
            ]

        # Return the minimum cost to paint all houses
        return min(dp)

