class Solution:
    def repeatedStringMatch(self, a: str, b: str) -> int:
        if len(b) % len(a) == 0:
            if b in a * (len(b) // len(a)):
                return len(a)
            else:
                return -1

        for i in range(1, len(b) + 1):
            if b in a * (i + 1):
                return i + 1
            elif b not in a * i:
                return -1

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        if len(s) > len(p):
            return False

        m, n = len(s), len(p)

        # Initialize a DP table
        dp = [[False] * (n + 1) for _ in range(m + 1)]

        # Base case: empty pattern matches empty string
        dp[0][0] = True

        # Fill the DP table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s[i - 1] == p[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                elif p[j - 1] == '?':
                    dp[i][j] = dp[i - 1][j - 1]
                elif p[j - 1] == '*':
                    # If the last character of p matches the last character of s, we can match any number of characters
                    dp[i][j] = dp[i - 1][j] or dp[i][j - 2]

        return dp[m][n]

class Solution:
    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        total_gas = 0
        current_gas = 0
        start_station = 0

        for i in range(len(gas)):
            total_gas += gas[i] - cost[i]
            current_gas += gas[i] - cost[i]

            if current_gas < 0:
                start_station = i + 1
                current_gas = 0

        return start_station if total_gas >= 0 else -1

class Solution:
    def allCellsDistOrder(self, rows: int, cols: int, rCenter: int, cCenter: int) -> List[List[int]]:
        return sorted([[i, j] for i in range(rows) for j in range(cols)], key=lambda x: abs(x[0] - rCenter) + abs(x[1] - cCenter))

class Solution:
    def movesToStamp(self, stamp: str, target: str) -> List[int]:
        m, n = len(stamp), len(target)
        target_list = list(target)
        result = []

        def can_stamp(start):
            for i in range(m):
                if target_list[start + i] != '?' and target_list[start + i] != stamp[i]:
                    return False
            return any(target_list[start + i] != '?' for i in range(m))

        while True:
            done = True
            for i in range(n - m + 1):
                if can_stamp(i):
                    done = False
                    result.append(i)
                    for j in range(m):
                        target_list[i + j] = '?'

            if done:
                break

        return result[::-1] if ''.join(target_list) == '?' * n else []

