class Solution:
    def getAllElements(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> List[int]:
        def inorder(root):
            if not root:
                return []
            return inorder(root.left) + [root.val] + inorder(root.right)
        return sorted(inorder(root1) + inorder(root2))

from collections import defaultdict, deque
from math import gcd

class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        n = len(nums)
        tree = defaultdict(list)
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        def dfs(node, parent):
            max_dist = -1
            max_val = -1
            for val in range(1, 51):
                if gcd(nums[node], val) == 1 and val in ancestor[val]:
                    dist = ancestor[val][val]
                    if dist > max_dist:
                        max_dist = dist
                        max_val = val
            res[node] = max_val

            old_ancestor = ancestor[nums[node]].copy()
            ancestor[nums[node]][nums[node]] = depth

            for neighbor in tree[node]:
                if neighbor != parent:
                    dfs(neighbor, node)

            ancestor[nums[node]] = old_ancestor

        ancestor = defaultdict(lambda: {i: -1 for i in range(1, 51)})
        res = [-1] * n
        depth = 0
        dfs(0, -1)
        return res

class Solution:
    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        sum1 = sum(nums1)
        sum2 = sum(nums2)
        count1 = nums1.count(0)
        count2 = nums2.count(0)

        # If sum1 is already greater than sum2, check if we can increase sum2 by replacing zeros
        if sum1 > sum2:
            if count2 == 0:
                return -1  # No zeros in nums2 to replace
            return max(sum1 + count2 * max(nums2), sum2 + count1 * max(nums1))

        # If sum1 is less than sum2, check if we can increase sum1 by replacing zeros
        if sum1 < sum2:
            if count1 == 0:
                return -1  # No zeros in nums1 to replace
            return max(sum1 + count2 * max(nums2), sum2 + count1 * max(nums1))

        # If sums are equal, no replacements are needed
        return sum1

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        n = len(strs)
        m = len(strs[0])
        ans = 0
        sorted_strs = [list(s) for s in strs]
        for j in range(m):
            for i in range(1, n):
                if sorted_strs[i-1][j] > sorted_strs[i][j]:
                    ans += 1
                    break
                elif sorted_strs[i-1][j] < sorted_strs[i][j]:
                    sorted_strs[i-1], sorted_strs[i] = sorted_strs[i], sorted_strs[i-1]
        return ans

class Solution:
    def subtreeWithAllDeepest(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        def dfs(node):
            if not node:
                return 0, None
            l_depth, l_node = dfs(node.left)
            r_depth, r_node = dfs(node.right)
            if l_depth == r_depth:
                return l_depth + 1, node
            elif l_depth > r_depth:
                return l_depth + 1, l_node
            else:
                return r_depth + 1, r_node

        return dfs(root)[1]

class Solution:
    def calculate(self, s: str) -> int:
        stack = []
        num = 0
        sign = '+'
        for char in s.replace(' ', ''):
            if char.isdigit():
                num = num * 10 + int(char)
            if not char.isdigit() or char == s[-1]:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    stack.append(int(stack.pop() / num))
                sign = char
                num = 0
        return sum(stack)

from collections import Counter

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n1, n2 = len(nums1), len(nums2)
        if n1 > n2 * 6 or n2 > n1 * 6:
            return -1

        diff = sum(nums2) - sum(nums1)
        if diff == 0:
            return 0

        if diff < 0:
            nums1, nums2 = nums2, nums1
            diff = -diff

        freq1 = Counter(nums1)
        freq2 = Counter(nums2)

        ops = 0
        for i in range(1, 7):
            if diff == 0:
                break
            # Fill up the smaller array with the maximum difference
            if freq1[i] + freq2[7 - i] > 0:
                fill = min(diff, freq1[i] * (7 - i) + freq2[7 - i] * i)
                diff -= fill
                ops += fill // (7 - i) + (fill % (7 - i) != 0)
                freq1[i] -= fill // (7 - i)
                freq2[7 - i] -= fill // (7 - i)
                if freq1[i] == 0:
                    del freq1[i]
                if freq2[7 - i] == 0:
                    del freq2[7 - i]

        return ops if diff == 0 else -1

class Solution:
    def equationsPossible(self, equations: List[str]) -> bool:
        # create an adjacency list to represent the graph
        graph = collections.defaultdict(set)
        for equation in equations:
            a, b = equation[0], equation[3]
            graph[a].add(b)
            graph[b].add(a)

        # check if there is a cycle in the graph
        visited = set()
        for node in graph:
            if node not in visited:
                stack = [node]
                while stack:
                    current = stack.pop()
                    visited.add(current)
                    for neighbor in graph[current]:
                        if neighbor not in visited:
                            stack.append(neighbor)

        # check if all variables are assigned
        return len(visited) == len(graph)

class Solution:
    def numKLenSubstrNoRepeats(self, s: str, k: int) -> int:
        if len(s) < k:
            return 0

        count = 0
        seen = set()

        for i in range(len(s)):
            while i < len(s) and s[i] in seen:
                seen.remove(s[i - k])
            seen.add(s[i])
            if len(seen) == k:
                count += 1

        return count

from collections import Counter

class Solution:
    def findTheLongestSubstring(self, s: str) -> int:
        # Dictionary to store the last index of each vowel
        last_index = {vowel: -1 for vowel in 'aeiou'}
        # Initialize variables to keep track of the current count of vowels and the maximum length of the valid substring
        current_count = 0
        max_length = 0

        # Iterate through each character in the string
        for i, char in enumerate(s):
            if char in 'aeiou':
                # Increment the count of the current vowel
                current_count += 1

                # If the current count exceeds the allowed number of vowels for that vowel,
                # update the last index of that vowel
                if current_count > 1:
                    last_index[char] = i

            else:
                # Reset the current count of vowels when encountering a non-vowel character
                current_count = 0

            # Update the maximum length of the valid substring
            max_length = max(max_length, i - last_index.get(char, -1))

        return max_length

class Solution:
    def largest1BorderedSquare(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        up = [[0] * cols for _ in range(rows)]
        left = [[0] * cols for _ in range(rows)]

        # Fill up and left arrays
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    up[i][j] = up[i-1][j] + 1 if i > 0 else 1
                    left[i][j] = left[i][j-1] + 1 if j > 0 else 1

        max_side = 0

        # Check each cell as potential bottom-right corner of the square
        for i in range(rows):
            for j in range(cols):
                min_side = min(up[i][j], left[i][j])
                while min_side > max_side:
                    if up[i-min_side+1][j] >= min_side and left[i][j-min_side+1] >= min_side:
                        max_side = min_side
                    min_side -= 1

        return max_side ** 2

class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        tasks.sort(key=lambda x: x[1])  # Sort tasks by their end times

        current_end = 0  # Initialize the current end time

        total_time = 0  # Initialize the total time

        for start, end, duration in tasks:
            if current_end <= start:  # If the current end time is less than or equal to the start time of the next task
                total_time += duration  # Add the duration to the total time
                current_end = end  # Update the current end time to the end time of the next task

        return total_time

class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        count = 0
        for i in range(len(nums1)):
            for j in range(len(nums2)):
                if nums1[i] % nums2[j] * k == 0:
                    count += 1
        return count

class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)

        # Helper function to check if a substring is a semi-palindrome
        def is_semi_palindrome(sub):
            for i in range(len(sub) // 2):
                if sub[i] != sub[-(i + 1)]:
                    return False
            return True

        # Helper function to calculate the minimum changes to make a substring a semi-palindrome
        def min_changes_to_semi_palindrome(sub):
            changes = 0
            for i in range(len(sub) // 2):
                if sub[i] != sub[-(i + 1)]:
                    changes += 1
            return changes

        # Recursive function to find the minimum changes
        @lru_cache(None)
        def dp(i, k):
            if k == 1:
                return min_changes_to_semi_palindrome(s[i:])
            ans = float('inf')
            for d in range(1, n - i + 1):
                if n % d == 0:
                    j = i + d
                    if is_semi_palindrome(s[i:j]):
                        ans = min(ans, dp(j, k - 1))
                    else:
                        ans = min(ans, min_changes_to_semi_palindrome(s[i:j]) + dp(j, k - 1))
            return ans

        return dp(0, k)

class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        if not nums:
            return 0

        current_and = nums[0]
        result = 1

        for num in nums[1:]:
            current_and &= num
            if current_and == 0:
                result += 1
                current_and = num

        return result

