class Solution:
    def nextGreaterElements(self, nums: List[int]) -> List[int]:
        n = len(nums)
        stack = []
        result = [-1] * n

        for i in range(n):
            while stack and nums[stack[-1]] < nums[i]:
                result[stack.pop()] = nums[i]

            stack.append(i)

        return result

class Solution:
    def longestDecomposition(self, text: str) -> int:
        left, right = 0, len(text) - 1
        left_str, right_str = "", ""
        count = 0

        while left < right:
            left_str += text[left]
            right_str = text[right] + right_str

            if left_str == right_str:
                count += 2
                left_str, right_str = "", ""

            left += 1
            right -= 1

        if left > right or left_str != "":
            count += 1

        return count

from typing import List
import heapq

class Solution:
    def getNumberOfBacklogOrders(self, orders: List[List[int]]) -> int:
        # Min heap for buy orders
        buy_orders = []
        # Max heap for sell orders
        sell_orders = []

        for price, amount, order_type in orders:
            if order_type == 0:  # Buy order
                while sell_orders and sell_orders[0][0] <= price and amount > 0:
                    sell_price, sell_amount = heapq.heappop(sell_orders)
                    if sell_amount > amount:
                        heapq.heappush(sell_orders, (sell_price, sell_amount - amount))
                        amount = 0
                    else:
                        amount -= sell_amount
                if amount > 0:
                    heapq.heappush(buy_orders, (-price, amount))
            else:  # Sell order
                while buy_orders and buy_orders[0][0] >= price and amount > 0:
                    buy_price, buy_amount = heapq.heappop(buy_orders)
                    if buy_amount > amount:
                        heapq.heappush(buy_orders, (buy_price, buy_amount - amount))
                        amount = 0
                    else:
                        amount -= buy_amount
                if amount > 0:
                    heapq.heappush(sell_orders, (price, amount))

        # Calculate the total amount of orders in the backlog
        total_backlog = 0
        for _, amount in buy_orders:
            total_backlog += amount
        for _, amount in sell_orders:
            total_backlog += amount

        # Return the result modulo 10^9 + 7
        return total_backlog % (10**9 + 7)

class Solution:
    def closestTarget(self, words: List[str], target: str, startIndex: int) -> int:
        n = len(words)
        if target not in words:
            return -1

        # Find the index of the target in the circular array
        target_index = (startIndex + words.index(target)) % n

        # Calculate the minimum distance to the target
        min_distance = float('inf')
        for i in range(n):
            if i != target_index:
                distance = abs(startIndex - (target_index + i))
                if distance < min_distance:
                    min_distance = distance

        return min_distance

