class Solution:
    def maxUpgrades(self, count: List[int], upgrade: List[int], sell: List[int], money: List[int]) -> List[int]:
        result = []
        for c, u, s, m in zip(count, upgrade, sell, money):
            if m >= u * c:
                result.append(c)
            else:
                profit_per_server = u - s
                if profit_per_server > 0:
                    max_sells = (m // s) if m >= s else 0
                    remaining_money = m - max_sells * s
                    upgrades = (remaining_money // profit_per_server) if remaining_money >= profit_per_server else 0
                    result.append(c - max_sells - upgrades)
                else:
                    result.append(0)
        return result

class Solution:
    def movesToMakeZigzag(self, nums: List[int]) -> int:
        def count_moves(arr):
            moves = 0
            for i in range(len(arr)):
                if i % 2 == 0:
                    left = arr[i - 1] if i > 0 else float('inf')
                    right = arr[i + 1] if i < len(arr) - 1 else float('inf')
                    if arr[i] >= min(left, right):
                        moves += arr[i] - min(left, right) + 1
                else:
                    left = arr[i - 1] if i > 0 else float('inf')
                    right = arr[i + 1] if i < len(arr) - 1 else float('inf')
                    if arr[i] >= max(left, right):
                        moves += arr[i] - max(left, right) + 1
            return moves

        return min(count_moves(nums), count_moves([x for x in reversed(nums)]))

# Definition for a binary tree node.
