#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def btreeGameWinningMove(self, root: Optional[TreeNode], n: int, x: int) -> bool:
        def dfs(node, color):
            if not node:
                return False

            # If the current node's value is equal to x, we have a winning move
            if node.val == x:
                return True

            # Check if the current node is a leaf node
            if not node.left and not node.right:
                return False

            # Check if there is a left neighbor of the current node
            if node.left and dfs(node.left, color ^ 1):
                return True

            # Check if there is a right neighbor of the current node
            if node.right and dfs(node.right, color ^ 1):
                return True

            # Check if there is a parent node of the current node
            if node.parent and dfs(node.parent, color ^ 1):
                return True

            # If none of the above conditions are met, we cannot win
            return False

        return dfs(root, 1)

class Solution:
    def smallestNumber(self, n: int) -> str:
        if n == 1:
            return "1"
        digits = []
        for i in range(9, 1, -1):
            while n % i == 0:
                digits.append(i)
                n //= i
        if n > 1:
            return "-1"
        return ''.join(sorted(map(str, digits), reverse=True))

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        def dfs(node, visited):
            for neighbor in range(len(graph)):
                if graph[node][neighbor] == 1 and neighbor not in visited:
                    visited.add(neighbor)
                    dfs(neighbor, visited)

        n = len(graph)
        initial.sort()  # Sort initial to ensure we return the smallest index in case of ties
        max_saved = 0
        best_node = initial[0]

        for node in initial:
            visited = set(initial) - {node}
            dfs(node, visited)
            saved = n - len(visited)

            if saved > max_saved:
                max_saved = saved
                best_node = node

        return best_node

class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    if length == 2 or s[i + 1] != s[j - 1]:
                        dp[i][j] = dp[i + 1][j - 1] + 2
                    else:
                        dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        return dp[0][n - 1]

class Solution:
    def smallestNumber(self, n: int) -> str:
        if n == 1:
            return "1"

        # If n is even, start with 2 and then use 3, 5, 7
        if n % 2 == 0:
            result = ""
            while n > 1:
                if n % 2 == 0:
                    result += "2"
                    n //= 2
                elif n % 3 == 0:
                    result += "3"
                    n //= 3
                elif n % 5 == 0:
                    result += "5"
                    n //= 5
                elif n % 7 == 0:
                    result += "7"
                    n //= 7
                else:
                    return "-1"
            return result

        # If n is odd, start with 3 and then use 2, 5, 7
        else:
            result = "3"
            while n > 1:
                if n % 2 == 0:
                    result += "2"
                    n //= 2
                elif n % 3 == 0:
                    result += "3"
                    n //= 3
                elif n % 5 == 0:
                    result += "5"
                    n //= 5
                elif n % 7 == 0:
                    result += "7"
                    n //= 7
                else:
                    return "-1"
            return result

class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        prefix_sum = 0

        for i in range(n):
            # Calculate the required value at index i
            required_value = prefix_sum + nums[i]

            # Check if the current value is valid
            if required_value < 0:
                return False

            # Update the prefix sum
            prefix_sum += nums[i]

            # Check if we need to adjust the next element
            if i + k < n:
                prefix_sum -= nums[i + k]

        return True

class Solution:
    def badSensor(self, sensor1: List[int], sensor2: List[int]) -> int:
        n = len(sensor1)

        # Check if sensor1 is the faulty sensor
        for i in range(n-1):
            if sensor1[:i] + sensor1[i+1:] == sensor2:
                return 1

        # Check if sensor2 is the faulty sensor
        for i in range(n-1):
            if sensor2[:i] + sensor2[i+1:] == sensor1:
                return 2

        # If neither sensor is faulty or it's indeterminate
        return -1

class Solution:
    def isLongPressedName(self, name: str, typed: str) -> bool:
        # Initialize pointers for both strings
        i, j = 0, 0

        # Iterate through both strings
        while i < len(name) and j < len(typed):
            # If the characters at the current pointers match, move both pointers forward
            if name[i] == typed[j]:
                i += 1
                j += 1
            # If the characters at the current pointers do not match, check if the next character in the typed string is longer
            elif typed[j] > name[i]:
                return False
            # If the next character in the typed string is the same as the current character in the name, move both pointers forward
            else:
                i += 1

        # If we have processed both strings, return True
        return i == len(name) and j == len(typed)

class Solution:
    def mergeTrees(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root1 and not root2:
            return None

        # Create a new node with the sum of the values of the current nodes
        new_node = TreeNode(root1.val + root2.val)

        # Recursively merge the left and right subtrees
        new_node.left = self.mergeTrees(root1.left, root2.left)
        new_node.right = self.mergeTrees(root1.right, root2.right)

        return new_node

class Solution:
    def maxOperations(self, nums: List[int], k: int) -> int:
        count = 0
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                if nums[i] + nums[j] == k:
                    count += 1
        return count

from typing import List

class Solution:
    def numPoints(self, darts: List[List[int]], r: int) -> int:
        def dist(p1, p2):
            return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

        def get_center_angle(p1, p2, r):
            d = dist(p1, p2)
            if d == 0 or d > 2 * r:
                return []
            h = (r ** 2 - (d / 2) ** 2) ** 0.5
            cx = (p1[0] + p2[0]) / 2 + (p1[1] - p2[1]) * h / d
            cy = (p1[1] + p2[1]) / 2 - (p1[0] - p2[0]) * h / d
            angle1 = (cx - p1[0], cy - p1[1])
            angle2 = (cx - p2[0], cy - p2[1])
            return [angle1, angle2]

        max_points = 1
        for i in range(len(darts)):
            for j in range(i + 1, len(darts)):
                centers = get_center_angle(darts[i], darts[j], r)
                for center in centers:
                    count = sum(1 for dart in darts if dist(center, dart) <= r)
                    max_points = max(max_points, count)
        return max_points

from typing import List

class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        rewardValues.sort()
        x = 0
        for value in rewardValues:
            if value > x:
                x += value
        return x

class Solution:
    def checkIfExist(self, arr: List[int]) -> bool:
        # Create a dictionary to store the elements we have seen so far
        seen = {}

        # Iterate through each element in the array
        for num in arr:
            # Check if the double of the current number has already been seen
            if num * 2 in seen:
                return True

            # Add the current number to the dictionary
            seen[num] = True

        # If no such pair is found, return False
        return False
